def f(x, y):
    s = x + y
    return s * (s + 1) // 2 + y

# Test the monotonicity constraint for small inputs (up to 4)
max_coord = 4
test_passed = True

for x1 in range(max_coord + 1):
    for y1 in range(max_coord + 1):
        for x2 in range(max_coord + 1):
            for y2 in range(max_coord + 1):
                if x1 == x2 and y1 == y2:
                    continue

                f1 = f(x1, y1)
                f2 = f(x2, y2)

                if f1 > f2:
                    # Check 1: f(x1+1, y1) > f(x2+1, y2)
                    try:
                        f1_plus_1_x = f(x1 + 1, y1)
                        f2_plus_1_x = f(x2 + 1, y2)
                        if f1_plus_1_x <= f2_plus_1_x:
                            print(f"Test Failed for f(x,y) = s(s+1)/2 + y:")
                            print(f"Pair 1: ({x1}, {y1}) -> {f1}")
                            print(f"Pair 2: ({x2}, {y2}) -> {f2}")
                            print(f"Check 1: f({x1+1}, {y1})={f1_plus_1_x} vs f({x2+1}, {y2})={f2_plus_1_x}. Fails.")
                            test_passed = False
                            break
                    except IndexError:
                        # Should not happen with range up to 4, but good practice
                        pass

                    # Check 2: f(x1, y1+1) > f(x2, y2+1)
                    try:
                        f1_plus_1_y = f(x1, y1 + 1)
                        f2_plus_1_y = f(x2, y2 + 1)
                        if f1_plus_1_y <= f2_plus_1_y:
                            print(f"Test Failed for f(x,y) = s(s+1)/2 + y:")
                            print(f"Pair 1: ({x1}, {y1}) -> {f1}")
                            print(f"Pair 2: ({x2}, {y2}) -> {f2}")
                            print(f"Check 2: f({x1}, {y1+1})={f1_plus_1_y} vs f({x2}, {y2+1})={f2_plus_1_y}. Fails.")
                            test_passed = False
                            break
                    except IndexError:
                        pass
            if not test_passed:
                break
        if not test_passed:
            break

if test_passed:
    print("\nMonotonicity constraint passed for f(x,y) = s(s+1)/2 + y up to coordinates 4.")
    print("Calculating parity matrix for 0 <= x, y < 5:")
    parity_matrix = []
    for x in range(5):
        row = []
        for y in range(5):
            val = f(x, y)
            parity = val % 2
            row.append(parity)
        parity_matrix.append(row)

    for row in parity_matrix:
        print(row)
else:
    print("\nTest failed.")

def T(s):
    return s * (s + 1) // 2

def f_parity(x, y):
    s = x + y
    t_s = T(s) % 2
    return (t_s + (y % 2)) % 2

N_count = 0
limit = 100
for x in range(limit):
    for y in range(limit):
        if f_parity(x, y) == 1:
            N_count += 1

print(f"N for f(x, y) = s(s+1)/2 + y in 100x100 grid: {N_count}")
